create table public.returns (id uuid primary key default gen_random_uuid(), store_id uuid not null, order_id uuid not null, user_id uuid references public.users(id) on delete set null, status text not null default 'requested' check(status in ('requested','approved','rejected','received','refunded','closed')), reason text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(store_id,order_id) references public.orders(store_id,id), unique(store_id,id));
